package br.com.admeclesial.interfaces.rest.matrimonio; import br.com.admeclesial.application.matrimonio.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/matrimonios") public class MatrimonioRestController { final MatrimonioApplicationService s; public MatrimonioRestController(MatrimonioApplicationService s){this.s=s;} @PostMapping public ResponseEntity<MatrimonioResponse> salvar(@Valid @RequestBody MatrimonioRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.salvar(r));} @GetMapping("/{uuid}") public MatrimonioResponse buscar(@PathVariable UUID uuid){return s.buscar(uuid);} @GetMapping("/por-processo/{uuid}") public MatrimonioResponse porProcesso(@PathVariable UUID uuid){return s.porProcesso(uuid);} }